    initCard: function initCard(isId, isType) {
      var _this4 = this;

      window.Rest.fetch({
        id: isId,
        types: 'card',
        subTypes: isType
      }).then(function (re) {
        if (re) {
          var _result = re.data; // console.log('#########################');
          // console.log(_result);
          // console.log('#########################');

          if (_result.hasOwnProperty('fail')) {
            alert(_result.fail);
          } else {
            _this4.initContents();

            var _card = _result.cards;
            var _cardNum = _result.cardsNum;
            _this4.cardsNum = _result.cardsNum;

            if (!_result.cardsNum) {
              _this4.cardsNum = [];
              _card = [];
              _cardNum = [];
            }

            _this4.talkState = false;

            if (_cardNum) {
              for (var i = 0; i < _card.length; i++) {
                _card[i].item = {};

                if (_card[i].type === 5 || _card[i].type === 12) {
                  _card[i].item = [];

                  _this4.chatInit(_card[i]);

                  _this4.talkState = true;
                } else if (_card[i].itemsNum) {
                  for (var j = 0; j < _card[i].with_items.length; j++) {
                    if (_card[i].with_items[j].with_comments) {
                      _card[i].with_items[j].comments = _.cloneDeep(_card[i].with_items[j].with_comments);
                    } else {
                      _card[i].with_items[j].comments = [];
                    }

                    if (_card[i].with_items[j].images && _card[i].with_items[j].images.length) {
                      for (var x = 0; x < _card[i].with_items[j].with_images.length; x++) {
                        if (_card[i].with_items[j].with_images[x].id === _card[i].with_items[j].images[0]) {
                          _card[i].with_items[j].image = _card[i].with_items[j].with_images[x];
                          break;
                        }
                      }
                    }

                    _card[i].with_items[j].isNew = false;
                    Vue.set(_this4.items, _card[i].with_items[j].id, _card[i].with_items[j]); // this.items[_card[i].with_items[j].id] = _card[i].with_items[j];
                  }
                } else {
                  _card[i].itemsNum = [];
                }

                Vue.set(_this4.cards, _card[i].id, _card[i]);
              }
            }

            _this4.initTempCard();

            if (_this4.myClass.userId === _this4.user.id) {
              _this4.isPro = true;
            } else {
              _this4.isPro = false;
            }
          } // this.forceRerender();

        } else {
          console.log('FETCH FAIL');
        }
      });
    },
    initTempCard: function initTempCard() {
      var tempCardData = JSON.parse(localStorage.getItem('tempCard'));

      if (_typeof(tempCardData) === 'object') {
        for (var key in tempCardData) {
          if (this.cardsNum.includes(tempCardData[key].cardId)) {
            var itemsNum = this.cards[tempCardData[key].cardId].itemsNum;
            itemsNum = _typeof(itemsNum) === 'object' || typeof itemsNum === 'array' ? itemsNum : [];
            var _itemsNum = [tempCardData[key].id];
            this.cards[tempCardData[key].cardId].itemsNum = _itemsNum.concat(itemsNum);
            Vue.set(this.items, tempCardData[key].id, tempCardData[key]);
            console.log(this.items);
          }
        }
      }
    },
    cardItemCommentFetch: function cardItemCommentFetch(_data) {
      var _this5 = this;

      window.Rest.fetch({
        id: _data.itemId,
        types: 'comment',
        subTypes: 'comment'
      }).then(function (re) {
        if (re) {
          // const _result = JSON.parse(re);
          var _result = re.data;
          var tempComments = [];

          if (_result.hasOwnProperty('fail')) {
            alert(_result.fail);
          } else {
            _result.forEach(function (com) {
              var date_ = new Date(com.updated_at);
              var year_ = date_.getFullYear();
              var month_ = 1 + date_.getMonth();
              var day_ = date_.getDate();
              var hour_ = date_.getHours();
              var minutes_ = date_.getMinutes();
              month_ = month_ >= 10 ? month_ : '0' + month_;
              day_ = day_ >= 10 ? day_ : '0' + day_;
              hour_ = hour_ >= 10 ? hour_ : '0' + hour_;
              minutes_ = minutes_ >= 10 ? minutes_ : '0' + minutes_;
              tempComments.push({
                id: com.id,
                itemId: com.itemId,
                userId: com.with_user.id,
                userName: com.with_user.name,
                date: year_ + '.' + month_ + '.' + day_ + '. ' + hour_ + ':' + minutes_,
                content: com.content,
                fileName: com.fileName,
                fileUrl: window.Rest.uri + '/download/' + com.id,
                file: '',
                commentMenu: false,
                editMode: false
              });
            });

            var cardIdx = -1;
            var itemIdx = -1;

            if (_this5.isTeamPage !== _data.isTeamPage) {
              var cardType = -1;

              if (_data.cardType === 1) {
                cardType = 10;
              } else if (_data.cardType === 2) {
                cardType = 7;
              }

              if (cardType !== -1) {
                for (var i = 0; i < _this5.cards.length; i++) {
                  if (_this5.cards[i].type === cardType) {
                    cardIdx = i;
                    break;
                  }
                }
              } else {
                console.log('?????');
              }
            } // else{
            //     for(let i=0;i<this.cards.length;i++){
            //         if(this.cards[i].id === _data.cardId){
            //             cardIdx = i;
            //             break;
            //         }
            //     }
            // }
            //
            // for(let i=0;i<this.cards[cardIdx].item.length;i++){
            //     if(this.cards[cardIdx].item[i].id === _data.itemId){
            //         itemIdx = i;
            //         break;
            //     }
            // }
            // this.cards[cardIdx].item[itemIdx].comments = tempComments;


            _this5.items[_data.itemId].comments = tempComments;
            console.log('TTTTTTTT');

            if (_this5.myItemModalUp) {
              if (!(cardIdx === -1 || itemIdx === -1)) {
                if (_this5.itemId === _data.itemId) {
                  _this5.$refs.itemModal.cardItemCommentFetch('UPDATE');
                }
              }
            }

            _this5.cards.push('1');

            _this5.cards.pop(); // this.forceRerender();

          }
        } else {
          console.log('FETCH FAIL');
        }
      });
    },
