    addComment: function addComment() {
      var _this12 = this;

      if (this.editor2.getHTML().length !== 7) {
        //멘션 누구에게 하는지 찾기
        var tempMentions = [];
        this.editor2.getJSON().content.forEach(function (tms) {
          if (tms.content) {
            tms.content.forEach(function (tm) {
              if (tm.type === 'mention' && tm.attrs) {
                tempMentions.push(Number(tm.attrs.id));
              }
            });
          }
        }); //ES6

        tempMentions = _.cloneDeep(Array.from(new Set(tempMentions)));
        console.log(tempMentions);
        window.Rest.update({
          id: this.isCardItem.id,
          types: 'item',
          subTypes: 'comment',
          content: this.editor2.getHTML(),
          file: this.commentFile,
          mentions: tempMentions
        }).then(function (re) {
          if (re) {
            var _result = re.data;

            if (_result.hasOwnProperty('fail')) {
              _this12.alertMsg = '댓글 내용을 입력해 주세요.';
              _this12.alertModal = true; //alert(_result.fail);
            } else {
              if (_result[0]) {
                var date_ = new Date(_result[0].created_at);
                var year_ = date_.getFullYear();
                var month_ = 1 + date_.getMonth();
                var day_ = date_.getDate();
                var hour_ = date_.getHours();
                var minutes_ = date_.getMinutes();
                month_ = month_ >= 10 ? month_ : '0' + month_;
                day_ = day_ >= 10 ? day_ : '0' + day_;
                hour_ = hour_ >= 10 ? hour_ : '0' + hour_;
                minutes_ = minutes_ >= 10 ? minutes_ : '0' + minutes_;
                var fileUrl = '';

                if (_result[0].filePathName) {
                  fileUrl = window.Rest.uri + '/download/' + _result[0].id;
                }

                _this12.isCardItem.comments.unshift({
                  id: _result[0].id,
                  itemId: _result[0].itemId,
                  userId: _result[0].with_user.id,
                  userName: _result[0].with_user.name,
                  date: year_ + '.' + month_ + '.' + day_ + '. ' + hour_ + ':' + minutes_,
                  content: _result[0].content,
                  fileName: _result[0].fileName,
                  fileUrl: fileUrl,
                  file: '',
                  commentMenu: false,
                  editMode: false
                }); // const po = this.searchIndex('item',_result[0].itemId);


                _this12.items[_this12.itemId].comments = _.cloneDeep(_this12.isCardItem.comments); // document.getElementById('textarea-input').lastChild.childNodes[0].childNodes[0].innerText = '';

                _this12.editor2.setContent('');

                _this12.commentFileName = '파일';
                _this12.commentFile = '';
                _this12.commentFileUrl = '';
              }
            }
          } else {
            console.log('FETCH FAIL');
          }
        });
      }
    },
    uploadFile: function uploadFile(e) {
      if (e.target.files[0] === undefined) {
        this.commentFileName = '파일';
        this.commentFile = '';
        this.commentFileUrl = '';
      } else {
        var pathpoint = e.target.files[0].name.lastIndexOf('.');
        var filepoint = e.target.files[0].name.substring(pathpoint + 1, e.target.files[0].name.length);
        var filetype = filepoint.toLowerCase();

        if (filetype == 'doc' || filetype == 'docx' || filetype == 'dotx' || filetype == 'xlsx' || filetype == 'xls' || filetype == 'hwp' || filetype == 'ppt' || filetype == 'pptx' || filetype == 'egg' || filetype == 'zip' || filetype == '7z' || filetype == 'tar' || filetype == 'zipx' || filetype == 'pdf') {
          this.commentFileName = e.target.files[0].name;
          this.commentFile = e.target.files[0];
          this.commentFileUrl = URL.createObjectURL(e.target.files[0]);
        } else {
          alert('해당 유형의 파일은 선택할 수 없습니다.');
          return false;
        }
      }
    },
    editUploadFile: function editUploadFile(e, com) {
      if (e.target.files[0] === undefined) {
        com.fileName = '파일';
        com.file = '';
        com.fileUrl = '';
      } else {
        var pathpoint = e.target.files[0].name.lastIndexOf('.');
        var filepoint = e.target.files[0].name.substring(pathpoint + 1, e.target.files[0].name.length);
        var filetype = filepoint.toLowerCase();

        if (filetype == 'doc' || filetype == 'docx' || filetype == 'dotx' || filetype == 'xlsx' || filetype == 'xls' || filetype == 'hwp' || filetype == 'ppt' || filetype == 'pptx' || filetype == 'egg' || filetype == 'zip' || filetype == '7z' || filetype == 'tar' || filetype == 'zipx' || filetype == 'pdf') {
          com.fileName = e.target.files[0].name;
          com.file = e.target.files[0];
          com.fileUrl = URL.createObjectURL(e.target.files[0]);
        } else {
          alert('해당 유형의 파일은 선택할 수 없습니다.');
          return false;
        }
      }
    },
